'use strict';
// Original companion questions, paraphrased from the inspected BSD project revisions.
const AUDIT_NOTES = [
  B('Cakupan kuis resmi: empat soal CSS telah dibaca di editor guru (sintaks, text-align, selector ID, dan class/border). Tiga belas soal media queries, Bootstrap, JavaScript, dan database belum diperiksa per butir. Panduan harian didasarkan pada proyek BSD yang ditelusuri; tantangan modifikasi disusun guru.|Official quiz scope: four CSS questions were read in the teacher editor (syntax, text-align, ID selector, and class/border). Thirteen media-query, Bootstrap, JavaScript, and database questions have not been inspected individually. Daily guides are based on the inspected BSD projects; modification challenges are teacher-written.'),
  B('Bank soal ini disusun guru sebagai pendamping, bukan salinan kuis resmi BSD. Fokus sumber merujuk proyek dan langkah yang diperiksa pada 13 Oktober 2026.|This is a teacher-written companion bank, not a copy of official BSD quizzes. Source focuses refer to project steps inspected on 13 October 2026.'),
  B('News: seed template memiliki title, image, dan content, tetapi belum memiliki tanggal. Siapkan tanggal yang valid pada salinan kerja sebelum menilai urutan terbaru; initDB menulis seed lagi saat dimuat.|News: template seeds contain title, image, and content, but no date. Provide valid dates in the working copy before assessing newest-first order; initDB writes the seeds again on load.'),
  B('Checkout: gunakan langkah 1–47. Langkah 48 berjudul “new step” kosong dan bukan target belajar. Ongkir standar 0 dan same-day 30 adalah angka simulasi proyek.|Checkout: use steps 1–47. Step 48, titled “new step”, is empty and is not a learning target. Standard shipping 0 and same-day shipping 30 are project simulation amounts.'),
  B('Produk disimpan bersama dalam array pada key allProducts. product.id memilih anggota array; order disimpan dengan key terpisah berawalan order. Jangan menyamakan kedua pola penyimpanan.|Products share an array at the allProducts key. product.id selects an array member; orders use separate keys beginning with order. Keep the two storage patterns distinct.'),
  B('Catatan konsep: justify-content mengatur sumbu utama; push mengembalikan panjang baru; sort() tanpa pembanding mengurutkan sebagai string. Untuk angka gunakan pembanding numerik. Gunakan penjelasan ini saat ringkasan sumber terlalu menyederhanakan.|Concept notes: justify-content controls the main axis; push returns the new length; sort() without a comparator sorts as strings. Use a numeric comparator for numbers. Use these explanations where a source summary oversimplifies.'),
  B('WKA, validasi tambahan, pengujian, dan refleksi sumatif adalah rancangan kelas. Satu soal per proyek mengecek konsep kunci; guru tetap meminta demonstrasi kode dan bukti tugas.|BCW, extra validation, testing, and summative reflection are classroom design. One question per project checks a key concept; the teacher still requests code demonstrations and task evidence.')
];
const lessonById = id => LESSONS.find(l => l.id === id);
function revise(id, fields) { Object.assign(lessonById(id), fields); }
function replaceQuestion(id, kind, index, ...args) { lessonById(id)[kind][index] = Q(...args); }
COURSE.timing = B('Rencana inti: 26 pertemuan × 90 menit, dengan review yang selektif sesuai diagnostik. Siapkan 2 workshop cadangan untuk cart, pengelolaan produk, dan integrasi: sekitar 28 pertemuan. Bila 2 JP hanya 80 menit, perkiraan awal 30–32 pertemuan; sesuaikan dari checkpoint. Alokasi resmi 19 pertemuan belum cukup untuk seluruh praktik mandiri dan demonstrasi.|Core plan: 26 meetings × 90 minutes, with review selected from diagnostics. Reserve 2 workshops for cart, product management, and integration: about 28 meetings. If two periods total only 80 minutes, initially allow 30–32 meetings; adjust using checkpoints. The existing 19-meeting allocation does not cover all independent practice and demonstrations.');
revise(1, {material:B('Pengantar BSD membahas B2C, B2B, C2C; manfaat dan kendala bagi pembeli serta penjual; pengalaman pelanggan; dan riset sustainability. Hubungkan satu keputusan website dengan manfaat dan tradeoff yang dapat diuji. Artikel 2019 dalam PDF adalah titik awal riset, bukan bukti kondisi perusahaan saat ini.|The BSD introduction covers B2C, B2B, C2C; buyer and vendor benefits and drawbacks; customer experience; and sustainability research. Connect one website decision to a testable benefit and tradeoff. The PDF’s 2019 article is a research starting point, not evidence of current company practices.'), tasks:[B('Klasifikasikan contoh B2C, B2B, C2C dan jelaskan pengguna toko usulanmu.|Classify B2C, B2B, and C2C examples and describe your proposed store’s users.'),B('Bandingkan satu manfaat dan satu kendala pembeli/penjual; amati pengalaman pelanggan.|Compare a buyer/vendor benefit and drawback; examine customer experience.'),B('Teliti satu praktik sustainability: sumber, efektivitas, keterbatasan, dan usulan perbaikan.|Research one sustainability practice: source, effectiveness, limitations, and an improvement.')],success:[B('Model transaksi dan pengguna dapat dijelaskan.|Transaction model and users can be explained.'),B('Manfaat, kendala, dan pengalaman pelanggan dibandingkan.|Benefits, drawbacks, and customer experience are compared.'),B('Klaim sustainability memiliki sumber, alasan, dan batasan.|A sustainability claim has sources, reasoning, and limitations.') ]});
replaceQuestion(1,'pre',0,'Perusahaan menjual langsung kepada konsumen. Model apa ini?|A company sells directly to consumers. Which model is this?','B2C.|B2C.','B2B.|B2B.','C2C.|C2C.','B2C berarti business to consumer; B2B antarbisnis, C2C antarkonsumen.|B2C means business to consumer; B2B is between businesses and C2C between consumers.');
revise(2,{material:B('Chatbot review memakai prompt, alert, variabel, dan if/else; Carrot Picker memakai klik, perubahan skor, dan pembaruan tampilan. Paper Art menambahkan lapisan parallax dengan data-depth serta animasi CSS @keyframes. Tinjau bagian yang belum dikuasai; satu pertemuan ini tidak menuntut mengulang seluruh 86 langkah dari awal.|The chatbot review uses prompt, alert, variables, and if/else; Carrot Picker uses clicks, score changes, and display updates. Paper Art adds parallax layers with data-depth and CSS @keyframes animations. Review gaps identified by diagnostics; this meeting does not require restarting all 86 steps.' )});
revise(3,{material:B('Image Card memakai selector, inline/inline-block, dan box model: content, padding, border, margin. Website Layout melatih float kiri/kanan, clear, list, dan kolom inline-block. Jelaskan mengapa footer perlu membersihkan float dan bagaimana ukuran kartu dihitung.|Image Card uses selectors, inline/inline-block, and the box model: content, padding, border, margin. Website Layout practises left/right floats, clear, lists, and inline-block columns. Explain why the footer clears floats and how card dimensions are calculated.')});
revise(4,{material:B('Gallery Website lebih dulu memakai float untuk sidebar dan area utama, clear untuk footer, serta hover dan jarak gambar. Flexbox Layout adalah proyek terpisah: direction, wrap, basis/grow, justify-content pada sumbu utama, align-items pada sumbu silang, dan align-self. Bandingkan hasil kedua cara layout.|Gallery Website first uses floats for the sidebar and main area, clear for the footer, and hover/image spacing. Flexbox Layout is a separate project: direction, wrap, basis/grow, justify-content on the main axis, align-items on the cross axis, and align-self. Compare the two layout approaches.')});
revise(5,{material:B('Mulai dari layout layar kecil. Proyek BSD menambah media query min-width 768px untuk tablet dan 992px untuk layar besar, lalu mengubah lebar container dan susunan berita dengan Flexbox. Uji di bawah, tepat pada, dan di atas breakpoint; angka pada soal penerapan lain adalah contoh latihan.|Start from the small-screen layout. BSD adds min-width media queries at 768px for tablets and 992px for large screens, then changes container width and the news layout using Flexbox. Test below, at, and above each breakpoint; numbers in other application questions are practice examples.')});
revise(6,{material:B('Bootstrap memakai grid 12 kolom: container → row → col, ukuran sm/md/lg, nested grid, dan offset. Perubahan kelas menentukan kapan kolom berubah susunan. Gunakan library versi proyek BSD dan uji dengan konten nyata.|Bootstrap uses a 12-column grid: container → row → col, sm/md/lg sizes, nested grids, and offsets. Classes determine when columns change arrangement. Use the BSD project’s library version and test with actual content.')});
revise(7,{material:B('Restaurant Home Page menggabungkan navbar yang collapse di mobile, carousel beserta kontrolnya, area About dengan grid, empat article cards, gambar responsif, dan footer. Uji target tombol dan dependensi komponen. Assignment 1 mandiri meminta minimal tiga cards, berbeda dari empat cards pada contoh restoran.|Restaurant Home Page combines a mobile collapsible navbar, carousel and controls, an About grid, four article cards, responsive images, and a footer. Test button targets and component dependencies. Independent Assignment 1 requires at least three cards, distinct from the restaurant example’s four.')});
revise(10,{material:B('Fundamentals melatih console.log, komentar, tipe string/number/boolean, prompt/alert, aritmetika, dan perubahan variabel. Conditional Statements memakai if/else if/else serta batas >, <, >=. Comparison and Logical Operators menggabungkan perbandingan, AND, OR, dan NOT. Prediksi keluaran sebelum menjalankan kode.|Fundamentals practises console.log, comments, string/number/boolean types, prompt/alert, arithmetic, and variable updates. Conditional Statements uses if/else if/else and >, <, >= boundaries. Comparison and Logical Operators combines comparisons, AND, OR, and NOT. Predict output before running code.')});
revise(11,{material:B('Functions: deklarasi, pemanggilan, parameter/argumen, dan return. Arrays: indeks dari 0, length, push/unshift, pop/shift, sort/reverse, dan indexOf. Loops: for, for…of, while, break, continue. Push mengembalikan panjang baru; sort() default membandingkan sebagai string, sehingga pengurutan angka memerlukan pembanding numerik.|Functions: declaration, calls, parameters/arguments, and return. Arrays: zero-based indices, length, push/unshift, pop/shift, sort/reverse, and indexOf. Loops: for, for…of, while, break, and continue. Push returns the new length; default sort() compares as strings, so numeric sorting needs a numeric comparator.')});
revise(12,{material:B('Proyek DOM memakai querySelector/querySelectorAll, getElementById, innerText/innerHTML, createElement, appendChild, style, dan classList.add/remove. Pilih elemen yang tepat lalu ubah teks, struktur, atau kelasnya. Sebagai pengayaan guru, textContent juga dapat menampilkan input sebagai teks biasa tanpa menafsirkannya sebagai HTML.|The DOM project uses querySelector/querySelectorAll, getElementById, innerText/innerHTML, createElement, appendChild, style, and classList.add/remove. Select the right element, then change its text, structure, or classes. As a teacher extension, textContent can also display input as plain text without interpreting it as HTML.')});
revise(13,{material:B('To-Do List lebih dulu membandingkan onclick, onchange, oninput, onkeydown, onkeyup, dan addEventListener, lalu membuat item DOM dari input dan menghapusnya dengan remove(). Target inti adalah tambah/hapus item dan memahami event. Pencegahan input kosong serta status selesai adalah pengayaan kelas; status selesai dan ID unik bukan fitur minimum proyek sumber.|To-Do List first compares onclick, onchange, oninput, onkeydown, onkeyup, and addEventListener, then creates DOM items from input and deletes them with remove(). Core targets are adding/removing items and understanding events. Empty-input prevention and completion status are classroom extensions; completion status and unique IDs are not minimum source-project features.'),tasks:[B('Bandingkan input, change, keydown, keyup; lanjutkan To-Do List dan check JavaScript.|Compare input, change, keydown, and keyup; complete To-Do List and the JavaScript check.'),B('Uji penambahan dua item dan hapus hanya item yang dipilih.|Test adding two items and removing only the selected item.'),B('Untuk Application Challenge, demonstrasikan modifikasi mandiri; misalnya validasi input kosong.|For the Application Challenge, demonstrate an independent modification, such as empty-input validation.')],success:[B('Tambah dan hapus item DOM bekerja.|Adding and removing DOM items works.'),B('Perbedaan event dijelaskan lewat hasil uji.|Event differences are explained through test results.'),B('Modifikasi mandiri dan alurnya dapat dijelaskan.|An independent modification and its flow can be explained.')]});
replaceQuestion(13,'post',1,'Tombol delete dibuat untuk newTodo. Operasi apa yang menghapus elemen item itu?|A delete button is created for newTodo. Which operation removes that item element?','newTodo.remove().|newTodo.remove().','Menghapus teks tombol saja.|Deleting only the button text.','Menghapus seluruh container daftar.|Removing the entire list container.','remove() pada item yang dipilih menghapus node itu; item lain tetap ada.|Calling remove() on the selected item removes that node while other items remain.');
revise(14,{material:B('Buka koneksi dengan await $BSD.db.open(nama), simpan koneksi pada db, lalu gunakan db.set/get/delete/listKeys. Nilainya bisa number, string, array, atau object. Proyek membaca hasil get dan listKeys dengan .then(...): hasil digunakan setelah operasi selesai. Database Manager membantu memeriksa key dan nilai.|Open a connection with await $BSD.db.open(name), store it in db, then use db.set/get/delete/listKeys. Values can be numbers, strings, arrays, or objects. The project reads get and listKeys results with .then(...): use results after the operation completes. Database Manager helps inspect keys and values.')});
revise(15,{material:B('Expense Tracker menyimpan object pengeluaran dengan key tersendiri. showAllExpenses memanggil listKeys, melakukan loop key, lalu get untuk membaca tiap nilai dan membangun DOM. Delete memakai key yang tepat, lalu daftar dan total diperbarui. Input biaya perlu dikonversi menjadi angka; reset form dilakukan setelah penyimpanan.|Expense Tracker stores each expense object at its own key. showAllExpenses calls listKeys, loops through keys, then calls get to read each value and build the DOM. Delete uses the correct key, followed by list/total updates. Convert cost input to a number; reset the form after saving.')});
revise(16,{material:B('Template sudah menyediakan seed array data1/data2 dengan title, image, content. initDB membuka news-website lalu menyimpan news dan recommended; siswa melengkapi loadNewsData dan loadRecommendedData agar membaca dan merender data. Seed ditulis kembali saat initDB berjalan. Belum ada field tanggal; persiapkan tanggal pada salinan kerja untuk tahap pengurutan.|The template supplies data1/data2 seed arrays with title, image, and content. initDB opens news-website and saves news and recommended; students complete loadNewsData and loadRecommendedData to read and render data. initDB writes seeds again on execution. There is no date field yet; prepare dates in the working copy for the ordering stage.'),tasks:[B('Periksa seed dan dua key news/recommended pada template siswa.|Inspect the seed and the two news/recommended keys in the student template.'),B('Lengkapi fungsi baca dan loop untuk area news serta recommended.|Complete read-and-loop functions for news and recommended areas.'),B('Tunjukkan alur data; siapkan tanggal valid bersama guru sebelum penilaian urutan.|Demonstrate the data flow; prepare valid dates with the teacher before assessing order.')]});
revise(17,{material:B('Brief meminta berita terbaru di atas, recommended news, responsivitas, dan penjelasan kode bersuara. Template belum menyediakan tanggal. Tambahkan/siapkan tanggal valid pada seed salinan kerja, sepakati cara membandingkannya, lalu uji tanggal berbeda. Jika seed masih ditulis tiap initDB, perubahan Database Manager saja bisa tertimpa ketika reload.|The brief asks for newest-first news, recommended news, responsiveness, and a narrated code explanation. The template has no dates. Add/provide valid dates in the working-copy seed, agree how to compare them, and test different dates. If initDB still writes seeds on every load, Database Manager edits alone may be overwritten on reload.')});
revise(18,{material:B('User Interface membangun toko statis dengan Bootstrap: navbar collapse, About dua kolom, tiga product cards, tombol Add to cart, footer, dan hover/scale gambar. Tombol cart belum menyimpan pesanan pada tahap ini; fungsi data datang di proyek berikutnya. Pengayaan kelas: pilih informasi produk yang mendukung keputusan sustainability secara jujur.|User Interface builds a static Bootstrap store: collapsible navbar, two-column About section, three product cards, Add to cart buttons, footer, and image hover/scale. Cart buttons do not store orders yet; data behaviour comes in later projects. Classroom extension: choose truthful product information supporting sustainability decisions.')});
revise(19,{material:B('Database Integration menyimpan array produk pada key allProducts, membaca dengan get().then(...), lalu forEach membangun cards menggunakan DOM. Product Modal Window meneruskan object productData dari produk yang diklik ke showDetail; gambar, teks, overlay, dan kelas active diperbarui. ID produk berada di dalam array, bukan key database terpisah per produk.|Database Integration stores the product array at allProducts, reads it with get().then(...), and uses forEach to build DOM cards. Product Modal Window passes the clicked productData object into showDetail; image, text, overlay, and active classes are updated. Product IDs are inside the array, not separate database keys for each product.'),tasks:[B('Lengkapi Database Integration dan Product Modal Window.|Complete Database Integration and Product Modal Window.'),B('Jelaskan allProducts, product.id, dan object yang diteruskan ke showDetail.|Explain allProducts, product.id, and the object passed to showDetail.'),B('Uji dua produk berbeda, tutup/buka modal, dan muat ulang data.|Test two different products, close/reopen the modal, and reread data.')]});
replaceQuestion(19,'pre',0,'Dalam array allProducts, apa yang membedakan satu produk dari produk lain?|Within the allProducts array, what distinguishes one product from another?','product.id.|product.id.','Key database harus berbeda untuk setiap card.|Every card must have a different database key.','Posisi CSS card saja.|Only the card’s CSS position.','allProducts adalah key koleksi; tiap object memiliki id. Modal menerima data produk yang dipilih.|allProducts is the collection key; each object has an id. The modal receives the selected product’s data.');
replaceQuestion(19,'post',0,'Modal selalu menampilkan produk pertama. Apa yang perlu diperiksa?|The modal always shows the first product. What should be checked?','Object productData yang diteruskan oleh handler klik ke showDetail.|The productData object passed by the click handler to showDetail.','Warna border saja.|Only the border colour.','Menambah key allProducts kedua.|Adding a second allProducts key.','Sumber memperbarui modal dari object produk yang diklik; periksa handler dan field yang dipakai.|The source updates the modal from the clicked product’s object; inspect the handler and fields used.');
revise(20,{material:B('Cart menyimpan pilihan pada array orders. Produk yang sudah ada menambah quantity, bukan baris duplikat. Jumlah barang dihitung price × quantity dan dijumlahkan; ketika quantity ≤ 0, splice menghapus item lalu render ulang. Uji dari card dan modal, tambah produk sama dua kali, ubah quantity, dan hapus hingga kosong. Proyek memiliki 68 langkah; workshop cadangan mungkin diperlukan.|Cart stores selections in the orders array. An existing product increments quantity instead of creating a duplicate row. Calculate price × quantity and sum items; when quantity ≤ 0, splice removes the item and the cart rerenders. Test from cards and the modal, add the same product twice, change quantities, and remove until empty. The project has 68 steps; a reserve workshop may be needed.')});
revise(21,{material:B('Checkout menambahkan nama, email, alamat, dan radio shipping. Standar gratis = 0; same-day = 30 pada simulasi sumber. Total barang ditambah shippingFee dan disimpan bersama orders serta timestamp pada key order + Date.now(). Setelah simpan, reset cart, input, ongkir, dan pilihan standar. Langkah 48 kosong; target selesai sampai Summary langkah 47. Validasi cart kosong dan feedback error adalah pengayaan kelas.|Checkout adds name, email, address, and shipping radio buttons. Standard shipping = 0; same-day = 30 in the source simulation. Add shippingFee to the item total and save it with orders and a timestamp at an order + Date.now() key. After saving, reset cart, inputs, fee, and standard selection. Step 48 is empty; finish at the step-47 Summary. Empty-cart validation and error feedback are classroom extensions.'),tasks:[B('Lengkapi langkah 1–47 Checkout dengan identitas uji, tanpa pembayaran nyata.|Complete Checkout steps 1–47 using test identities, without real payments.'),B('Uji input wajib, pergantian ongkir 0/30, dan total yang disimpan.|Test required inputs, shipping changes 0/30, and the saved total.'),B('Periksa order tersimpan dan reset form/cart; tambahkan uji cart kosong.|Check the saved order and form/cart reset; add an empty-cart test.')],success:[B('Field wajib diperiksa sebelum save.|Required fields are checked before saving.'),B('Order sesuai barang, ongkir, dan total checkout.|The order matches items, shipping fee, and checkout total.'),B('Setelah save, cart dan form direset; kasus tambahan diuji.|After saving, cart and form reset; additional cases are tested.')]});
revise(22,{material:B('Backend User Interface masih memakai contoh tabel/card dan navigasi yang mengganti kelas container. User Orders membuka database yang sama, memakai listKeys("order"), membaca tiap key dengan get, lalu membuat baris nama/email/alamat, barang, total, dan tanggal. Hapus dummy data dan kosongkan tabel sebelum render ulang. Keamanan server adalah pembahasan tambahan guru, bukan fitur otomatis dari halaman ini.|Backend User Interface still uses sample tables/cards and navigation that changes container classes. User Orders opens the same database, calls listKeys("order"), reads each key with get, then builds rows for name/email/address, items, total, and date. Remove dummy data and clear the table before rerendering. Server security is an additional teacher discussion, not an automatic feature of this page.')});
replaceQuestion(22,'post',1,'Pesanan muncul dua kali setelah daftar dibaca ulang. Apa yang perlu diperbaiki?|Orders appear twice after the list is reread. What needs fixing?','Kosongkan isi tabel sebelum membuat baris dari hasil baca baru.|Clear the table before creating rows from the new read result.','Sembunyikan seluruh halaman.|Hide the whole page.','Ubah setiap order menjadi produk.|Turn every order into a product.','Langkah 20 mereset tabel; ini mencegah baris lama menumpuk dengan baris baru.|Step 20 resets the table, preventing old rows from accumulating with new rows.');
revise(23,{material:B('Show Products membaca db.get("allProducts") dan merender array setelah membersihkan baris lama. Edit Products mengisi form dari productData, menyimpan id pada hidden input, mencari anggota array dengan id itu, mengubah field, lalu db.set("allProducts", allProducts). Key koleksi tetap sama; product.id menentukan produk yang diubah.|Show Products reads db.get("allProducts") and renders the array after clearing old rows. Edit Products fills the form from productData, stores the id in a hidden input, finds that array member, updates fields, then calls db.set("allProducts", allProducts). The collection key stays the same; product.id selects the product to edit.'),tasks:[B('Lengkapi Show Products dan Edit Products.|Complete Show Products and Edit Products.'),B('Pilih produk dengan id dari hidden input, edit field, lalu simpan array ke allProducts.|Select by the hidden-input id, edit fields, and save the array to allProducts.'),B('Baca ulang kedua tampilan; pastikan produk lain tidak berubah.|Reread both views; confirm other products are unchanged.')]});
replaceQuestion(23,'pre',0,'Dalam Edit Products, apa yang memilih anggota array yang akan diubah?|In Edit Products, what selects the array member to update?','ID produk pada hidden input, dicocokkan dengan product.id.|The product ID in the hidden input, matched with product.id.','Key database baru untuk setiap perubahan harga.|A new database key for every price change.','Nama kelas CSS sidebar.|The sidebar CSS class name.','ID memilih anggota allProducts; array yang diperbarui disimpan kembali pada key allProducts.|The ID selects an allProducts member; the updated array is saved back at allProducts.');
revise(24,{goal:B('Menambah dan menghapus produk pada koleksi allProducts, lalu menguji transaksi lengkap.|Add and delete products in allProducts, then test a complete transaction.'),material:B('New Product mencakup create DAN delete. Form memeriksa field kosong, membuat object dengan id timestamp dan harga parseFloat, push ke allProducts, lalu menyimpan array. Delete meminta konfirmasi, filter berdasarkan product.id, simpan updatedProducts pada key allProducts, dan refresh. ID timestamp adalah contoh proyek; jangan menganggapnya jaminan unik untuk semua sistem nyata.|New Product covers create AND delete. The form checks empty fields, creates an object with a timestamp id and parseFloat price, pushes it into allProducts, and saves the array. Delete requests confirmation, filters by product.id, saves updatedProducts at allProducts, and refreshes. Timestamp IDs are a project example, not a uniqueness guarantee for every real system.'),tasks:[B('Lengkapi New Product, termasuk validasi form dan delete langkah 33–42.|Complete New Product, including form validation and deletion in steps 33–42.'),B('Tambah produk, batalkan satu delete, lalu konfirmasi delete produk uji lain.|Add a product, cancel one deletion, then confirm deletion of another test product.'),B('Periksa array tersimpan dan kedua tampilan; jalankan transaksi lengkap untuk produk baru.|Check the saved array and both views; run a complete transaction for the new product.')],success:[B('Produk baru memiliki id pembeda di dalam array allProducts.|The new product has a distinguishing id inside allProducts.'),B('Delete yang dibatalkan mempertahankan data; delete yang dikonfirmasi tersimpan.|Cancelled deletion preserves data; confirmed deletion persists.'),B('Field, harga, refresh, dan transaksi produk baru diuji.|Fields, price, refresh, and a new-product transaction are tested.')]});
replaceQuestion(24,'post',0,'Dua produk dalam allProducts mempunyai id sama. Apa risikonya?|Two products in allProducts have the same id. What is the risk?','Edit/delete berdasarkan id dapat mengenai produk yang salah atau lebih dari satu.|ID-based editing/deletion may affect the wrong product or multiple products.','Array otomatis membuat kedua id berbeda.|The array automatically changes the IDs.','Key allProducts harus diganti untuk setiap produk.|The allProducts key must change for every product.','Key allProducts memang dipakai bersama; identitas anggota array harus dapat dibedakan.|The allProducts key is intentionally shared; array members must have distinguishable identities.');

revise(2,{tasks:[B('Gunakan diagnostik untuk memilih bagian review yang perlu ditinjau, bukan mengulang semua langkah.|Use diagnostics to select review gaps rather than restarting every step.'),B('Ubah satu respons chatbot atau aturan skor game; demonstrasikan input, event, dan output.|Change a chatbot response or game scoring rule; demonstrate input, event, and output.'),B('Pada Paper Art, jelaskan satu data-depth atau @keyframes dan prediksi perubahan gerakannya.|In Paper Art, explain one data-depth or @keyframes rule and predict a movement change.')]});
revise(3,{tasks:[B('Kerjakan Image Card dan Website Layout; identifikasi selector, inline-block, float, dan clear.|Work on Image Card and Website Layout; identify selectors, inline-block, float, and clear.'),B('Ganti konten kartu; bandingkan padding, border, margin, dan total lebarnya.|Replace card content; compare padding, border, margin, and total width.'),B('Tunjukkan layout kolom dan footer di bawah float; periksa keterbacaan.|Demonstrate columns and a footer below floats; check readability.')],success:[B('Kartu dan box model dapat dijelaskan.|The card and its box model can be explained.'),B('Float/clear dan inline-block dapat ditunjukkan pada layout.|Float/clear and inline-block can be demonstrated in the layout.'),B('Konten terbaca, spacing dan heading konsisten.|Content is readable; spacing and headings are consistent.')]});
